var errSettingsNotInitialized = errors.New("vercel settings cache not initialized")

// InitSettings loads repository settings for the current worktree and stores
// them in a small package cache keyed by worktree root.
func InitSettings(ctx context.Context) error {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return err
	}

	cachedSettingsMu.RLock()
	if cachedSettings != nil && cachedSettingsRoot == root {
		cachedSettingsMu.RUnlock()
		return nil
	}
	cachedSettingsMu.RUnlock()

	s, err := settings.Load(ctx)
	if err != nil {
