	}

	cachedSettingsMu.Lock()
	cachedSettingsRoot = root
	cachedSettings = s
	cachedSettingsMu.Unlock()

	return nil
}

// CachedSettings returns the most recently initialized repository settings for
// the given worktree root.
func CachedSettings(root string) (*settings.EntireSettings, error) {
	cachedSettingsMu.RLock()
	defer cachedSettingsMu.RUnlock()
	if cachedSettings == nil || cachedSettingsRoot != root {
		return nil, errSettingsNotInitialized
	}
	return cachedSettings, nil
}

// Load reads an existing Vercel config file if present.
func Load(path string, exists bool) (map[string]any, bool, error) {
