// MaybeMergeMetadataBranchVercelConfig ensures the metadata branch contains the
// Vercel deployment-disable rule when the repository has Vercel integration enabled.
// Existing vercel.json content is preserved and merged when present.
func MaybeMergeMetadataBranchVercelConfig(repo *git.Repository, rootTreeHash plumbing.Hash) (plumbing.Hash, error) {
	worktree, worktreeErr := repo.Worktree()
	if worktreeErr != nil {
		return rootTreeHash, nil
	}

	projectSettings, settingsErr := vercelconfig.CachedSettings(worktree.Filesystem.Root())
	if settingsErr != nil || !projectSettings.Vercel {
		return rootTreeHash, nil
	}

	config := make(map[string]any)
	var existingContents string
	if rootTreeHash != plumbing.ZeroHash {
		tree, treeErr := repo.TreeObject(rootTreeHash)
		if treeErr != nil && !errors.Is(treeErr, plumbing.ErrObjectNotFound) {
			return plumbing.ZeroHash, fmt.Errorf("read metadata tree: %w", treeErr)
		}
		if treeErr == nil {
			file, fileErr := tree.File(vercelconfig.FileName)
			if fileErr == nil {
				contents, contentsErr := file.Contents()
				if contentsErr != nil {
					return plumbing.ZeroHash, fmt.Errorf("read %s from metadata branch: %w", vercelconfig.FileName, contentsErr)
				}
				existingContents = contents
				if unmarshalErr := json.Unmarshal([]byte(contents), &config); unmarshalErr != nil {
					config = make(map[string]any)
				}
			}
		}
	}

	vercelconfig.MergeDeploymentDisabled(config)
	output, err := vercelconfig.Marshal(config)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("marshal %s: %w", vercelconfig.FileName, err)
	}
	if string(output) == existingContents {
		return rootTreeHash, nil
	}

	blobHash, err := CreateBlobFromContent(repo, output)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("create %s blob: %w", vercelconfig.FileName, err)
	}

	newTreeHash, err := UpdateSubtree(repo, rootTreeHash, nil, []object.TreeEntry{
		{Name: vercelconfig.FileName, Mode: filemode.Regular, Hash: blobHash},
	}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("update metadata subtree with %s: %w", vercelconfig.FileName, err)
	}

	return newTreeHash, nil
}

package vercelconfig

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"path/filepath"
	"sync"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const (
	BranchPattern = "entire/**"
	FileName      = "vercel.json"
)

var (
	cachedSettingsMu   sync.RWMutex
	cachedSettingsRoot string
	cachedSettings     *settings.EntireSettings
)

var errSettingsNotInitialized = errors.New("vercel settings cache not initialized")

// InitSettings loads repository settings for the current worktree and stores
// them in a small package cache keyed by worktree root.
func InitSettings(ctx context.Context) error {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return err
	}
	root = normalizeRoot(root)

	cachedSettingsMu.RLock()
	if cachedSettings != nil && cachedSettingsRoot == root {
		cachedSettingsMu.RUnlock()
		return nil
	}
	cachedSettingsMu.RUnlock()

	s, err := settings.Load(ctx)
	if err != nil {
		return err
	}

	cachedSettingsMu.Lock()
	cachedSettingsRoot = root
	cachedSettings = s
	cachedSettingsMu.Unlock()

	return nil
}

// CachedSettings returns the most recently initialized repository settings for
// the given worktree root.
func CachedSettings(root string) (*settings.EntireSettings, error) {
	root = normalizeRoot(root)
	cachedSettingsMu.RLock()
	defer cachedSettingsMu.RUnlock()
	if cachedSettings == nil || cachedSettingsRoot != root {
		return nil, errSettingsNotInitialized
	}
	return cachedSettings, nil
}

func normalizeRoot(root string) string {
	root = filepath.Clean(root)
	resolved, err := filepath.EvalSymlinks(root)
	if err != nil {
		return root
	}
	return filepath.Clean(resolved)
}

// Load reads an existing Vercel config file if present.
func Load(path string, exists bool) (map[string]any, bool, error) {
	if !exists {
		return make(map[string]any), false, nil
	}

	data, err := osReadFile(path)
	if err != nil {
		return nil, false, fmt.Errorf("read %s: %w", FileName, err)
	}

	var config map[string]any
	if err := json.Unmarshal(data, &config); err != nil {
		return nil, false, fmt.Errorf("parse %s: %w", FileName, err)
	}
	if config == nil {
		config = make(map[string]any)
	}

	return config, DeploymentDisabled(config), nil
}

// DeploymentDisabled reports whether Entire branches are disabled in the config.
func DeploymentDisabled(config map[string]any) bool {
	gitConfig, ok := config["git"].(map[string]any)
	if !ok {
		return false
	}
	deploymentEnabled, ok := gitConfig["deploymentEnabled"].(map[string]any)
	if !ok {
		return false
	}
	enabled, ok := deploymentEnabled[BranchPattern].(bool)
	return ok && !enabled
}

// MergeDeploymentDisabled sets deploymentEnabled["entire/**"] = false while preserving other fields.
func MergeDeploymentDisabled(config map[string]any) {
	gitConfig, ok := config["git"].(map[string]any)
	if !ok {
		gitConfig = make(map[string]any)
		config["git"] = gitConfig
	}

	deploymentEnabled, ok := gitConfig["deploymentEnabled"].(map[string]any)
	if !ok {
		deploymentEnabled = make(map[string]any)
		gitConfig["deploymentEnabled"] = deploymentEnabled
	}

	deploymentEnabled[BranchPattern] = false
}

// Marshal formats a Vercel config with a trailing newline.
func Marshal(config map[string]any) ([]byte, error) {
	output, err := jsonutil.MarshalIndentWithNewline(config, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("marshal %s: %w", FileName, err)
	}
	return output, nil
}

